import express from 'express';
import { WebSocketServer } from 'ws';
import {
  NET, TICK_DT, FIELD, GOAL, PLAYER, STAMINA, BALL, KICK, MATCH, ROOM, TEAM, TEAM_COLORS, NAME_MAX_LENGTH, PHASE, spawnPositions, GOAL_CENTER, TARGET_GOAL, integratePlayer
} from './core.js';

